}
html[data-bo-theme="dark"]:has(body.bo-wallet-tx){
  background-color:#2C2E38;
  background-image:linear-gradient(90deg,
    #3A3226 0,
    #342E28 calc(var(--sidebar-w,280px) * .72),
    #2F2E32 var(--sidebar-w,280px),
