    #2C2E38 100%
  );
  background-attachment:fixed;
  background-repeat:no-repeat;
  background-size:100% 100%;
  min-height:100%;
}

body.bo-wallet-tx .report-shell,
body.bo-wallet-tx .report-main,
body.bo-wallet-tx .report-content{
  background:transparent!important;
}

/* ---- Fixed listing frame (mirror Admin Detail `.mad-panel`) ----
   Viewport-locked shell: table panel fills remaining height; rows scroll inside. */
body.bo-wallet-tx .report-main{
  min-height:100vh!important;
  min-height:100dvh!important;
  height:100vh!important;
  height:100dvh!important;
  display:flex!important;
  flex-direction:column!important;
  overflow:hidden!important;
}
body.bo-wallet-tx .report-topbar{
  flex:0 0 auto!important;
}
body.bo-wallet-tx .report-content{
  flex:1 1 auto!important;
  min-height:0!important;
  display:flex!important;
  flex-direction:column!important;
  gap:16px!important;
  overflow:hidden!important;
  padding-bottom:16px!important;
}
body.bo-wallet-tx .report-content > .quick-stats,
body.bo-wallet-tx .report-content > .filter-card,
body.bo-wallet-tx .report-content > .user-title-row,
body.bo-wallet-tx .report-content > .bo-page-head{
  flex:0 0 auto!important;
}
body.bo-wallet-tx .report-content > .table-card,
body.bo-wallet-tx .report-content .table-card{
  flex:1 1 auto!important;
  flex-grow:1!important;
  min-height:0!important;
  margin-bottom:0!important;
  height:auto!important;
  max-height:none!important;
  align-self:stretch!important;
}

/* ---- Sidebar (beat reports.css blue) ---- */
body.bo-wallet-tx .report-sidebar{
  background:var(--bo-sidebar-bg)!important;
  border-right:1px solid rgba(92,74,48,.14)!important;
  color:var(--bo-sidebar-text)!important;
  box-shadow:none!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .report-sidebar{
  border-right-color:rgba(245,158,11,.22)!important;
}
body.bo-wallet-tx .report-sidebar::before{
  content:"";
  position:absolute;
  top:12%;bottom:12%;right:0;
  width:2px;
  border-radius:999px 0 0 999px;
  pointer-events:none;z-index:2;
  background:linear-gradient(180deg, transparent 0%, #F59E0B 26%, #D97706 58%, transparent 100%);
  opacity:.75;
}
body.bo-wallet-tx .report-sidebar > *{position:relative;z-index:1}
body.bo-wallet-tx .report-brand{
  height:var(--bo-header-h)!important;
  min-height:var(--bo-header-h)!important;
  max-height:var(--bo-header-h)!important;
  box-sizing:border-box!important;
  color:var(--bo-sidebar-text)!important;
  border-bottom:1px solid var(--bo-border)!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .report-brand{
  border-bottom-color:rgba(255,255,255,.12)!important;
  color:#fff!important;
}
body.bo-wallet-tx .report-brand small{
  color:var(--bo-sidebar-text)!important;
  font-weight:bold!important;
