  letter-spacing:.14em!important;
  opacity:.78;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .report-brand small{
  color:rgba(245,158,11,.78)!important;
  opacity:1;
}
body.bo-wallet-tx .close-side{
  color:var(--bo-sidebar-text)!important;
  border-color:rgba(92,74,48,.18)!important;
  background:transparent!important;
}

/* Kill legacy blue nav-group gradient (reports.css) */
body.bo-wallet-tx .report-sidebar .nav-group{
