body.bo-wallet-tx .bo-tx-toolbar{
  display:flex!important;
  flex-flow:row nowrap!important;
  align-items:center!important;
  justify-content:space-between!important;
  gap:12px 16px!important;
  width:100%!important;
  min-width:0!important;
}
body.bo-wallet-tx .bo-tx-tabs{
  display:inline-flex!important;
  align-items:center!important;
  gap:6px!important;
  flex:0 0 auto!important;
  position:relative!important;
  min-height:36px!important;
  padding:0!important;
  margin:0!important;
  background:transparent!important;
  border:0!important;
  border-radius:0!important;
  overflow:visible!important;
}
body.bo-wallet-tx .bo-tx-tabs.bo-seg > .bo-seg-thumb{
  top:0!important;
  height:100%!important;
  border-radius:999px!important;
  background-color:#F3E8D6!important;
  background-image:linear-gradient(180deg,#FFF8EB 0%,#F3E8D6 100%)!important;
  border:1px solid #EADCC8!important;
  box-shadow:0 1px 2px rgba(24,25,28,.06),0 2px 6px rgba(24,25,28,.05)!important;
  box-sizing:border-box!important;
  opacity:1;
}
body.bo-wallet-tx .bo-tx-tab{
  display:inline-flex!important;
  align-items:center!important;
  position:relative!important;
  z-index:1!important;
  height:36px!important;
  min-height:36px!important;
  padding:0 14px!important;
  margin:0!important;
  gap:8px!important;
  border:1px solid transparent!important;
  border-bottom:1px solid transparent!important;
  border-radius:999px!important;
  background:transparent!important;
  color:#71717A!important;
  font-size:12.5px!important;
  font-weight:700!important;
  line-height:1!important;
  text-decoration:none!important;
  white-space:nowrap!important;
  cursor:pointer!important;
  box-shadow:none!important;
  transition:color .16s ease,background .16s ease!important;
}
/* Soft busy while list refetch — keep rows visible, no Loading wipe flash. */
body.bo-wallet-tx .table-card.is-tx-busy .bo-tx-table-body,
body.bo-wallet-tx .table-card.is-tx-busy .bo-tx-table-head{
  opacity:.78;
  pointer-events:none;
}
body.bo-wallet-tx .bo-tx-tab[data-bo-tx-type="deposit"]::before,
body.bo-wallet-tx .bo-tx-tab[data-bo-tx-type="withdraw"]::before{
  content:""!important;
  width:6px!important;
  height:6px!important;
  border-radius:50%!important;
  flex:0 0 auto!important;
  background:#B8C0CC!important;
  box-shadow:none!important;
}
body.bo-wallet-tx .bo-tx-tab[data-bo-tx-type="withdraw"]::before{
  background:#C4C0D0!important;
}
body.bo-wallet-tx .bo-tx-tab:hover:not(.is-active){
  color:#18191C!important;
  background:rgba(24,25,28,.04)!important;
}
body.bo-wallet-tx .bo-tx-tab.is-active,
body.bo-wallet-tx .bo-tx-tab[aria-current="page"]{
  color:#18191C!important;
  font-weight:700!important;
  background:transparent!important;
  border-color:transparent!important;
  border-bottom-color:transparent!important;
  box-shadow:none!important;
}
/* Fallback when bo-seg thumb is absent */
body.bo-wallet-tx .bo-tx-tabs:not(.bo-seg) .bo-tx-tab.is-active,
body.bo-wallet-tx .bo-tx-tabs:not(.bo-seg) .bo-tx-tab[aria-current="page"]{
  background-color:#F3E8D6!important;
  background-image:linear-gradient(180deg,#FFF8EB 0%,#F3E8D6 100%)!important;
  border-color:#EADCC8!important;
  box-shadow:0 1px 2px rgba(24,25,28,.06),0 2px 6px rgba(24,25,28,.05)!important;
}
body.bo-wallet-tx .bo-tx-tab.is-active[data-bo-tx-type="deposit"]::before,
body.bo-wallet-tx .bo-tx-tab[aria-current="page"][data-bo-tx-type="deposit"]::before{
