  font-weight:700!important;
  font-variant-numeric:tabular-nums!important;
  color:inherit!important;
}
body.bo-wallet-tx .bo-tx-tab-count::before{content:"("!important;}
body.bo-wallet-tx .bo-tx-tab-count::after{content:")"!important;}
