body.bo-wallet-tx.deposit-approval-page .approval-pending-stats.deposit-bank-card-stats,
body.deposit-approval-page .approval-pending-stats.deposit-bank-card-stats,
body.bo-wallet-tx.withdraw-approval-page .approval-pending-stats.deposit-bank-card-stats,
body.withdraw-approval-page .approval-pending-stats.deposit-bank-card-stats{
  display:grid!important;
  grid-template-columns:repeat(auto-fit,minmax(220px,1fr))!important;
  gap:12px!important;
  margin-bottom:14px!important;
}
body.bo-wallet-tx .deposit-bank-card{
  display:flex!important;
  flex-direction:column!important;
  gap:12px!important;
  min-height:0!important;
  padding:14px 14px 12px!important;
  border-radius:8px!important;
  background:var(--bo-surface,#FFF8EB)!important;
  border:1px solid var(--bo-border,#EADCC8)!important;
  box-shadow:none!important;
  color:var(--bo-text,#18191C)!important;
}
body.bo-wallet-tx .deposit-bank-card-head{
  display:flex!important;
  align-items:center!important;
  gap:10px!important;
  min-width:0!important;
}
body.bo-wallet-tx .deposit-bank-mark{
  flex:0 0 36px!important;
  width:36px!important;
  height:36px!important;
  border-radius:8px!important;
  display:inline-grid!important;
  place-items:center!important;
  font-size:14px!important;
  font-weight:800!important;
  letter-spacing:-0.02em!important;
  color:#B45309!important;
  background:rgba(217,119,6,.12)!important;
  border:1px solid rgba(217,119,6,.22)!important;
}
body.bo-wallet-tx .deposit-bank-id{
  min-width:0!important;
  display:flex!important;
  flex-direction:column!important;
  gap:2px!important;
}
body.bo-wallet-tx .deposit-bank-id b{
  font-size:13px!important;
  font-weight:800!important;
  line-height:1.2!important;
  color:var(--bo-text,#18191C)!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  white-space:nowrap!important;
}
body.bo-wallet-tx .deposit-bank-id small{
  font-size:11px!important;
  font-weight:600!important;
  line-height:1.25!important;
  color:var(--bo-muted,#78716C)!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  white-space:nowrap!important;
}
body.bo-wallet-tx .deposit-bank-total{
  display:flex!important;
  flex-direction:column!important;
  gap:0!important;
  padding-top:2px!important;
}
body.bo-wallet-tx .deposit-bank-total > strong{
  display:block!important;
  margin:0!important;
  font-size:24px!important;
  font-weight:800!important;
  line-height:1.05!important;
  letter-spacing:-0.03em!important;
  color:var(--bo-text,#18191C)!important;
  font-variant-numeric:tabular-nums!important;
}
body.bo-wallet-tx .deposit-bank-meter{
  display:flex!important;
  flex-direction:column!important;
  gap:6px!important;
  margin-top:auto!important;
  padding-top:2px!important;
}
body.bo-wallet-tx .deposit-bank-meter-line{
  display:flex!important;
  justify-content:space-between!important;
  align-items:center!important;
  gap:8px!important;
  font-size:11px!important;
  font-weight:700!important;
  color:var(--bo-muted,#78716C)!important;
}
body.bo-wallet-tx .deposit-bank-track{
  order:-1!important;
  height:8px!important;
  border-radius:999px!important;
  overflow:hidden!important;
  background:#EDE4D4!important;
  border:1px solid #DCC9A8!important;
  box-shadow:inset 0 1px 2px rgba(107,54,12,.06)!important;
}
body.bo-wallet-tx .deposit-bank-fill{
  height:100%!important;
  border-radius:999px!important;
  max-width:100%!important;
  min-width:0!important;
  background:linear-gradient(90deg,#FBBF24,#D97706)!important;
  transition:width .22s ease!important;
}
body.bo-wallet-tx .deposit-bank-fill.is-warn{
  background:linear-gradient(90deg,#F59E0B,#B45309)!important;
}
body.bo-wallet-tx .deposit-bank-fill.is-over{
  background:linear-gradient(90deg,#F87171,#B91C1C)!important;
}
body.bo-wallet-tx .deposit-bank-meter.is-empty .deposit-bank-track{
  background:repeating-linear-gradient(-45deg,#EDE4D4 0 6px,#E8D9C4 6px 12px)!important;
}
body.bo-wallet-tx .deposit-bank-meter.is-empty .deposit-bank-fill{
  width:0!important;
  background:transparent!important;
}
body.bo-wallet-tx .deposit-bank-card.is-empty .bo-summary-note{
  font-size:12px!important;
  color:var(--bo-muted,#78716C)!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-card{
  background:#383A46!important;
  border-color:rgba(255,255,255,.14)!important;
  color:#F5F5F4!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-mark{
  color:#FBBF24!important;
  background:rgba(245,158,11,.16)!important;
  border-color:rgba(245,158,11,.28)!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-id b,
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-total > strong{
  color:#F5F5F4!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-id small,
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-meter-line,
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-card.is-empty .bo-summary-note{
  color:#A1A1AA!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-track{
  background:#2A2C36!important;
  border-color:rgba(255,255,255,.12)!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-fill{
  background:linear-gradient(90deg,#FBBF24,#F59E0B)!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-fill.is-warn{
  background:linear-gradient(90deg,#F59E0B,#D97706)!important;
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-fill.is-over{
  background:linear-gradient(90deg,#F87171,#DC2626)!important;
}
@media (prefers-reduced-motion:reduce){
  body.bo-wallet-tx .deposit-bank-fill{transition:none!important}
}
html[data-bo-theme="dark"] body.bo-wallet-tx .deposit-bank-meter.is-empty .deposit-bank-fill{
