@media (max-width:1439.98px){
  body.bo-wallet-tx.deposit-approval-page .approval-pending-stats.deposit-bank-card-stats,
body.bo-wallet-tx.withdraw-approval-page .approval-pending-stats.deposit-bank-card-stats{
    grid-template-columns:repeat(auto-fit,minmax(200px,1fr))!important;
    gap:10px!important;
  }
}

/* Bank cards: one-row snap strip whenever the grid would wrap into 2+ rows.
   Keeps the table panel tall enough to show ledger rows with internal scroll. */
@media (max-width:1280px){
  body.bo-wallet-tx.deposit-approval-page .approval-pending-stats.deposit-bank-card-stats,
body.bo-wallet-tx.withdraw-approval-page .approval-pending-stats.deposit-bank-card-stats{
    display:flex!important;
    flex-flow:row nowrap!important;
    align-items:stretch!important;
    gap:10px!important;
    overflow-x:auto!important;
    overflow-y:hidden!important;
    -webkit-overflow-scrolling:touch;
    scroll-snap-type:x mandatory;
    padding-bottom:4px!important;
    margin-bottom:10px!important;
    max-height:none!important;
    scrollbar-width:thin;
  }
  body.bo-wallet-tx.deposit-approval-page .deposit-bank-card,
body.bo-wallet-tx.withdraw-approval-page .deposit-bank-card{
    flex:0 0 220px!important;
    width:220px!important;
    max-width:220px!important;
    scroll-snap-align:start;
  }
  /* Table panel must keep a usable height; rows scroll inside .bo-tx-table-body */
  body.bo-wallet-tx.deposit-approval-page .report-content > .table-card,
body.bo-wallet-tx.withdraw-approval-page .report-content > .table-card{
    flex:1 1 auto!important;
    min-height:min(52vh,420px)!important;
  }
  body.bo-wallet-tx.deposit-approval-page .bo-tx-table-body,
body.bo-wallet-tx.withdraw-approval-page .bo-tx-table-body{
    flex:1 1 auto!important;
    min-height:160px!important;
    overflow-x:auto!important;
    overflow-y:auto!important;
    -webkit-overflow-scrolling:touch;
